-- CHAMBA 018 — Columnas faltantes al aprobar técnico (operational_phase, assigned_worker_id)SET statement_timeout = '120s';ALTER TABLE jobs  ADD COLUMN IF NOT EXISTS assigned_worker_id UUID REFERENCES profiles(id);ALTER TABLE jobs  ADD COLUMN IF NOT EXISTS operational_phase TEXT;DO $$BEGIN  ALTER TABLE jobs DROP CONSTRAINT IF EXISTS jobs_operational_phase_check;EXCEPTION  WHEN undefined_object THEN NULL;END $$;ALTER TABLE jobs  ADD CONSTRAINT jobs_operational_phase_check  CHECK (    operational_phase IS NULL    OR operational_phase IN ('accepted', 'en_route', 'arrived', 'completed')  );-- Asegurar RPC de aprobar técnico (usa operational_phase)CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS client_approve_worker_application CASCADE;CREATE OR REPLACE FUNCTION client_approve_worker_application(  p_job_id    UUID,  p_client_id UUID,  p_worker_id UUID)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_job jobs%ROWTYPE;  v_assignment_id UUID;BEGIN  SELECT * INTO v_job FROM jobs WHERE id = p_job_id FOR UPDATE;  IF NOT FOUND OR v_job.created_by <> p_client_id THEN    RETURN jsonb_build_object('success', false, 'error', 'Solicitud no encontrada');  END IF;  IF v_job.status::text <> 'open' THEN    RETURN jsonb_build_object('success', false, 'error', 'Esta solicitud ya fue asignada');  END IF;  SELECT id INTO v_assignment_id  FROM job_assignments  WHERE job_id = p_job_id    AND worker_id = p_worker_id    AND selection_status = 'pending';  IF v_assignment_id IS NULL THEN    RETURN jsonb_build_object('success', false, 'error', 'Este técnico no tiene una postulación activa');  END IF;  UPDATE job_assignments  SET selection_status = 'approved'  WHERE id = v_assignment_id;  UPDATE job_assignments  SET selection_status = 'rejected'  WHERE job_id = p_job_id    AND selection_status = 'pending'    AND worker_id <> p_worker_id;  UPDATE jobs  SET status = 'taken',      assigned_worker_id = p_worker_id,      slots_taken = COALESCE(slots_taken, 0) + 1,      operational_phase = 'accepted',      updated_at = NOW()  WHERE id = p_job_id;  RETURN jsonb_build_object(    'success', true,    'assignment_id', v_assignment_id,    'worker_id', p_worker_id  );END;$$;GRANT EXECUTE ON FUNCTION client_approve_worker_application(UUID, UUID, UUID)  TO authenticated, anon;